import { UICore } from 'data:application/javascript;base64,';
import { UIPanels } from 'data:application/javascript;base64,';
import { UIRadio } from 'data:application/javascript;base64,';
import { UIWorkshop } from 'data:application/javascript;base64,';
import { UINotifications } from 'data:application/javascript;base64,';

export class UIManager {
    constructor(game) {
        this.game = game;
        this.core = new UICore(game);
        this.panels = new UIPanels(game);
        this.radio = new UIRadio(game);
        this.workshop = new UIWorkshop(game);
        this.notifications = new UINotifications();
        
        // Delegate properties to core for backward compatibility
        this.joystickEnabled = false;
    }

    init() {
        this.updateAllUI();
        this.setupAllEventListeners();
    }
    
    updateAllUI() {
        this.core.updateAllUI();
        this.radio.updateRadioUI();
    }
    
    setupAllEventListeners() {
        this.core.setupDrawerToggles();
        this.panels.setupControlsToggle();
        this.panels.setupAchievementsPanel();
        this.panels.setupResetButton();
        this.workshop.setupWorkshopPanel();
        this.radio.setupRadioPanel();
    }

    // Delegate methods to appropriate modules
    updateMissionUI(mission) { this.core.updateMissionUI(mission); }
    updateMoneyUI(money) { this.core.updateMoneyUI(money); }
    updateCompanyStatusUI(companyStarted, money) { this.core.updateCompanyStatusUI(companyStarted, money); }
    updateLevelUI(level, xp, xpForNextLevel) { this.core.updateLevelUI(level, xp, xpForNextLevel); }
    updateSpeedometer(speed, maxSpeed, gear, cruise) { this.core.updateSpeedometer(speed, maxSpeed, gear, cruise); }
    setupVehicleShop(ownedVehicles, selectedVehicle, money) { this.core.setupVehicleShop(ownedVehicles, selectedVehicle, money); }
    updateAchievementsUI(unlockedAchievements) { this.panels.updateAchievementsUI(unlockedAchievements); }
    updateRadioUI() { this.radio.updateRadioUI(); }
    updateRadioCountry(country) { this.radio.updateRadioCountry(country); }
    showWorkshopPanel() { this.workshop.showWorkshopPanel(); }
}